L15_1.m_Pos = "C"
L15_1.m_Crash = 10
L15_1.m_Talk_KOREA = "그때, 지원자가 엄청 몰렸다가, 관리국 감사 때문에 다들 지원을 취소해 버렸잖아?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "あの時、最初は志願者が多かったけど、管理局の監査のせいでみんなキャンセルになったじゃない？"
L15_1.m_Talk_ENG = "There was a huge flood of applicants at first, but then everyone backed out after the Administration audit, right?"
L15_1.m_Talk_TWN = "那時候，申請者蜂擁而至，但因為管理局的審查，大家都取消了申請，不是嗎？"
L15_1.m_Talk_SCN = "那时候，申请者蜂拥而至，但因为管理局的审查，大家都取消了申请，不是吗？"
L15_1.m_Talk_DEU = "There was a huge flood of applicants at first, but then everyone backed out after the Administration audit, right?"
L15_1.m_Talk_FRA = "There was a huge flood of applicants at first, but then everyone backed out after the Administration audit, right?"
