L17_1.m_CharStrID = L18_1
L18_1 = "마지막 승부에서 네가 오지만디아스를 막아주지 않았다면 아마도 우리는 졌을 거야."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "最後の勝負でミナがオジマンディアスを止めてくれなかったら、多分私たちは負けてたよ。"
