L27_1.m_bCharHologramEffect = true
L28_1 = "멤버 불화설, 지분 문제, 등등……. 뭐, 여러 추측성 루머가 나돌긴 했지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "メンバーの不仲説、取り分をめぐる問題だとか……いろんな憶測が出回ったわ。"
