L28_1 = "Rumors flew around... including infighting between members, disputes over shares, and all kinds of speculation."
L27_1.m_Talk_ENG = L28_1
L28_1 = "成員不和的傳聞、股份問題等等……嗯，各種猜測性的傳聞確實很多。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "成员不和的传闻、股份问题等等……嗯，各种猜测性的传闻确实很多。"
