L39_1 = "INTERN_FENRIR_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "모두 힘을 합쳐서 꿈을 이루어서 너무 기뻐요!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "みんなで力を合わせて夢を叶えられて、本当に嬉しいです！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I'm so happy that everyone got together and achieved this dream!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "大家同心協力實現夢想，我真的好開心！"
