L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "INTERN_FENRIR_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "리그에서 우승해서 펜릴 소대의 이름을 드높였으니, 펜릴 소대 동상이 세워지겠죠?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "リーグで優勝したことでフェンリル小隊の名もあげられましたし、フェンリル小隊の銅像も建てられるでしょうね？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Since we won, the reputation of Fenrir Squad must have gone up. Do you think they'll put up a Fenrir Squad statue?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "聯賽中奪冠後，芬里爾小隊知名度也因此大大提升，那應該會建一個芬里爾小隊的銅像吧？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "既然在联赛中夺冠，让芬里尔小队名声大振了，那应该会建一个芬里尔小队铜像吧！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Since we won, the reputation of Fenrir Squad must have gone up. Do you think they'll put up a Fenrir Squad statue?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Since we won, the reputation of Fenrir Squad must have gone up. Do you think they'll put up a Fenrir Squad statue?"
