L40_1.m_CharStrID = L41_1
L41_1 = "이 영광을 소대장님과 선배님들께 바칩니다아!!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "この栄光を、小隊長と先輩方に捧げますぅ！！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I dedicate this honor to our commander and my fellow Fenrir Squad members!!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "我要把這份榮耀獻給小隊長和前輩們！！"
