L41_1.m_CharStrID = L42_1
L42_1 = "하하, 동상까지는 몰라도 우릴 본딴 액션 피규어는 나올 거예요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "銅像が建つかどうかはわかりませんが、私たちのフィギュアぐらいなら作られると思いますよ。"
