L45_1 = "LAIKA_CANARY_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "리그 상금만으로도 몇 년은 일 안하고 먹고 살 수 있을 걸?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "リーグの賞金だけでも数年は働かなくても生きていける金額だぞ？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "With the league's prize money, we can live a comfortable life for a few years without having to work!"
