L29_1.m_Pos = "R"
L30_1 = "그러니까… 누가 뭐래도 나는 나 스스로를 믿고, 그 녀석을 찾아내겠어……!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "だから……誰になんと言われようと、私は自分を信じてあいつを見つけ出す……！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "So no matter what anyone says, I'll trust myself and I'll find her...!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "所以……無論別人怎麼說，我都相信自己，一定會找到那傢伙……！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "所以……无论别人怎么说，我都相信自己，一定会找到那家伙……！"
