L30_1 = "So no matter what anyone says, I'll trust myself and I'll find her...!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "So no matter what anyone says, I'll trust myself and I'll find her...!"
L29_1.m_Talk_FRA = L30_1
